template:
{%- set prefixes = value.get("prefixes") or {} -%}
<div class="studio-editor studio-stylesheet" data-studio-editor-item data-studio-kind="stylesheet" data-studio-mode="edit" data-studio-stylesheet="{{ value.name }}" data-studio-applies-to="{{ value.get("applies_to") or "" }}">
<p class="studio-sheet-name"><span class="studio-field-label">Name</span> <strong>{{ value.name }}</strong></p>
<div class="studio-sheet-fields">
{%- if "applies_to" in children %}{{ children["applies_to"] }}{% else %}<span class="studio-field"><label class="studio-field-label" for="{{ input_id }}-applies-to">Applies to</label><input id="{{ input_id }}-applies-to" class="studio-field-input" type="text" name="/applies_to" value="" data-studio-field spellcheck="false"></span>{% endif %}
{%- if "order" in children %}{{ children["order"] }}{% else %}<span class="studio-field"><label class="studio-field-label" for="{{ input_id }}-order">Order</label><input id="{{ input_id }}-order" class="studio-field-input" type="number" step="1" name="/order" value="" placeholder="0" data-studio-field></span>{% endif %}
</div>
<fieldset class="studio-prefixes"><legend>Prefixes</legend>
{%- for key, iri in prefixes|dictsort %}
<div class="studio-prefix"><label class="studio-prefix-key" for="{{ input_id }}-prefix-{{ loop.index }}">{{ key }}</label> <input id="{{ input_id }}-prefix-{{ loop.index }}" class="studio-field-input" type="text" name="/prefixes/{{ key|replace("~", "~0")|replace("/", "~1") }}" value="{{ iri }}" data-studio-field spellcheck="false"></div>
{%- endfor %}
<div class="studio-prefix studio-prefix-new" data-studio-prefix-new><input type="text" class="studio-field-input studio-prefix-key-input" aria-label="New prefix" placeholder="new prefix" data-studio-prefix-key data-studio-field spellcheck="false"> <input type="text" class="studio-field-input" aria-label="The new prefix's IRI" placeholder="IRI" data-studio-prefix-iri data-studio-field spellcheck="false"></div>
</fieldset>
{%- if "rules" in children %}
{{ children["rules"] }}
{%- else %}
<div class="studio-rules"><h4 class="studio-rules-title">Rules</h4><div class="studio-rule-append"><label for="{{ input_id }}-new-select">New rule's selector</label><input type="text" id="{{ input_id }}-new-select" class="studio-field-input" name="/rules/-/select" data-studio-field spellcheck="false"><label for="{{ input_id }}-new-component">New rule's component</label><input type="text" id="{{ input_id }}-new-component" class="studio-field-input" name="/rules/-/component" data-studio-field spellcheck="false"><button type="submit" class="studio-add-rule">Add rule</button></div></div>
{%- endif %}
<div class="studio-editor-actions"><button type="submit" class="studio-save">Save</button></div>
</div>
